58	// startServer 在 dataDir 上启动真实服务子进程（--port 0 自动选端口），返回基地址。
59	function startServer(t, dataDir) {
60	  const proc = spawn(
61	    serverBin,
62	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
63	    { stdio: ['ignore', 'pipe', 'inherit'] },
64	  );
65	  t.after(() => { proc.kill('SIGKILL'); });
66	  return new Promise((resolve, reject) => {
67	    let buf = '';
68	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
69	    proc.stdout.on('data', (chunk) => {
70	      buf += chunk.toString();
71	      const m = buf.match(/listening on (http:\/\/\S+)/);
72	      if (m) {
73	        clearTimeout(timer);
74	        resolve(m[1]);
75	      }
76	    });
77	    proc.on('exit', (code) => {
78	      clearTimeout(timer);
79	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
80	    });
81	  });
82	}
