801	// setupGatedPage 启动带种子数据的真实服务，但在打开页面之前挂起第一次列表查询，
802	// 让测试可以在“第一次查询仍在途”的状态下模拟创建与第二次查询。records 为 []
803	// 时对应“创建前一个房间都没有”的数据目录。
804	async function setupGatedPage(t, records) {
805	  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
806	  t.after(() => rm(dataDir, { recursive: true, force: true }));
807	  await seedRooms(dataDir, ...records);
808	  const baseURL = await startServer(t, dataDir);
809	  const page = await browser.newPage();
810	  t.after(() => page.close());
811	  await page.setRequestInterception(true);
812	  const lists = gateRoomLists(page);
813	  await page.goto(baseURL, { waitUntil: 'load' });
814	  await lists.waitFor(1); // 打开页面触发的第一次查询已在途，结果由测试掌握。
815	  return { page, baseURL, lists };
816	}
817	
818	// setupPlainPage 用于无交错基线：不拦截任何请求，页面加载后查询自然返回。
819	async function setupPlainPage(t, records) {
820	  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
821	  t.after(() => rm(dataDir, { recursive: true, force: true }));
822	  await seedRooms(dataDir, ...records);
823	  const baseURL = await startServer(t, dataDir);
824	  const page = await browser.newPage();
825	  t.after(() => page.close());
826	  await page.goto(baseURL, { waitUntil: 'load' });
827	  return { page, baseURL };
828	}
