830	// createRoomWithListsHeld 在第一次查询仍挂起时填写并提交表单，等待 POST 真实
831	// 成功、创建后的第二次列表查询已经发起（同样挂起），返回创建结果。
832	async function createRoomWithListsHeld(page, lists, fillForm) {
833	  const createdPromise = nextCreated(page);
834	  await fillForm();
835	  await page.click('#submit');
836	  const created = await createdPromise;
837	  await lists.waitFor(2); // 创建成功触发的第二次查询已在途。
838	  return created;
839	}
