  // 两端：普通空格 + U+0085 + U+00A0（应去掉），紧挨内容的 U+FEFF（应保留）；
  // 内部：U+00A0 与普通空格（应保留）；补充平面表情（应保留且只算 1 个码点）。
  const rawName = '\u00A0\u0085 \uFEFF周末\u00A0棋室🀄 \uFEFF \u0085\u00A0';
  const trimmedName = '\uFEFF周末\u00A0棋室🀄 \uFEFF';
