59	// load 读取数据文件，返回顶层数组中的原始记录以及已占用的房间编号。
60	// 文件无法读取或不是合法数组时返回错误，绝不重置已有数据。
61	// 数组中的非对象元素原样保留（兼容历史记录及其附带字段）。
62	func (s *roomStore) load() ([]json.RawMessage, map[string]bool, error) {
63		raw, err := os.ReadFile(s.path)
64		if err != nil {
65			return nil, nil, fmt.Errorf("读取房间数据失败: %w", err)
66		}
67		var records []json.RawMessage
68		if err := json.Unmarshal(raw, &records); err != nil {
69			return nil, nil, fmt.Errorf("房间数据不是合法的数组: %w", err)
70		}
71		used := make(map[string]bool, len(records))
72		for _, rec := range records {
73			var probe struct {
74				ID string `json:"id"`
75			}
76			if err := json.Unmarshal(rec, &probe); err == nil && probe.ID != "" {
77				used[probe.ID] = true
78			}
79		}
80		return records, used, nil
81	}
82	
83	// create 校验配置、写入新记录并返回保存后的房间。
84	func (s *roomStore) create(cfg roomConfig) (room, int, error) {
85		if code, msg, ok := validateConfig(cfg); !ok {
86			return room{}, code, errors.New(msg)
87		}
88	
89		s.mu.Lock()
90		defer s.mu.Unlock()
91	
92		records, used, err := s.load()
93		if err != nil {
94			return room{}, http.StatusInternalServerError, err
95		}
96	
97		now := time.Now()
98		newRoom := room{
99			ID:          uniqueRoomID(used),
100			Name:        strings.TrimSpace(cfg.Name),
101			Game:        cfg.Game,
102			Capacity:    cfg.Capacity,
103			TurnSeconds: cfg.TurnSeconds,
104			Status:      "waiting",
105			Visibility:  "public",
106			CreatedAt:   now.UTC().Format(time.RFC3339),
107		}
108	
109		encoded, err := json.Marshal(newRoom)
110		if err != nil {
111			return room{}, http.StatusInternalServerError, fmt.Errorf("序列化房间记录失败: %w", err)
112		}
113		records = append(records, encoded)
114		if err := s.writeAtomic(records); err != nil {
115			return room{}, http.StatusInternalServerError, err
116		}
117		return newRoom, http.StatusCreated, nil
118	}
119	
120	// writeAtomic 先写临时文件再重命名，避免保存失败时破坏原有数据。
121	func (s *roomStore) writeAtomic(records []json.RawMessage) error {
122		payload, err := json.MarshalIndent(records, "", "  ")
123		if err != nil {
124			return fmt.Errorf("序列化房间数据失败: %w", err)
125		}
126		payload = append(payload, '\n')
127	
128		dir := filepath.Dir(s.path)
129		tmp, err := os.CreateTemp(dir, ".rooms-*.tmp")
130		if err != nil {
131			return fmt.Errorf("创建临时数据文件失败: %w", err)
132		}
133		tmpName := tmp.Name()
134		cleanup := func() { _ = os.Remove(tmpName) }
135	
136		if _, err := tmp.Write(payload); err != nil {
137			_ = tmp.Close()
138			cleanup()
139			return fmt.Errorf("写入房间数据失败: %w", err)
140		}
141		if err := tmp.Sync(); err != nil {
142			_ = tmp.Close()
143			cleanup()
144			return fmt.Errorf("同步房间数据失败: %w", err)
145		}
146		if err := tmp.Close(); err != nil {
147			cleanup()
148			return fmt.Errorf("关闭临时数据文件失败: %w", err)
149		}
150		if err := os.Rename(tmpName, s.path); err != nil {
151			cleanup()
152			return fmt.Errorf("保存房间数据失败: %w", err)
153		}
154		return nil
155	}
156	
157	func uniqueRoomID(used map[string]bool) string {
158		var b [16]byte
159		for {
160			if _, err := rand.Read(b[:]); err != nil {
161				panic(fmt.Errorf("生成房间编号失败: %w", err))
162			}
163			id := hex.EncodeToString(b[:])
164			if !used[id] {
165				return id
166			}
167		}
168	}
169	
170	// validateConfig 执行全部字段校验，返回 http 状态码与具体原因。
171	// 所有字段都必须明确提交且合法，不使用任何默认值。
172	func validateConfig(cfg roomConfig) (int, string, bool) {
173		name := strings.TrimSpace(cfg.Name)
174		if name == "" {
175			return http.StatusBadRequest, "房间名称不能为空", false
176		}
177		if len([]rune(name)) > 40 {
178			return http.StatusBadRequest, "房间名称去掉首尾空白后不能超过 40 个字符", false
179		}
180	
181		switch cfg.Game {
182		case "gomoku":
183			if cfg.Capacity != 2 {
184				return http.StatusBadRequest, "五子棋的人数上限固定为 2 人", false
185			}
186		case "ludo":
187			if cfg.Capacity < 2 || cfg.Capacity > 4 {
188				return http.StatusBadRequest, "飞行棋的人数上限必须为 2 至 4 人", false
189			}
190		default:
191			return http.StatusBadRequest, "未知游戏规则，目前仅支持 gomoku（五子棋）和 ludo（飞行棋）", false
192		}
193	
194		if cfg.TurnSeconds != 0 && (cfg.TurnSeconds < 10 || cfg.TurnSeconds > 600) {
195			return http.StatusBadRequest, "每步时间限制只能为 0（不限时）或 10 至 600 秒之间的整数", false
196		}
197		return 0, "", true
198	}
199	
200	func respond(w http.ResponseWriter, status int, value any) {
201		w.Header().Set("Content-Type", "application/json; charset=utf-8")
202		w.WriteHeader(status)
203		_ = json.NewEncoder(w).Encode(value)
204	}
205	
206	func methodNotAllowed(w http.ResponseWriter, allow string) {
207		w.Header().Set("Content-Type", "application/json; charset=utf-8")
208		w.Header().Set("Allow", allow)
209		w.WriteHeader(http.StatusMethodNotAllowed)
210		_ = json.NewEncoder(w).Encode(map[string]string{"error": "method not allowed"})
211	}
212	
213	func run() error {
214		if len(os.Args) < 2 {
215			printHelp()
216			return errors.New("expected serve or --help")
217		}
218		if os.Args[1] == "--help" || os.Args[1] == "-h" {
219			printHelp()
220			return nil
221		}
222		if os.Args[1] != "serve" {
223			return errors.New("expected serve or --help")
224		}
225		args := flag.NewFlagSet("score-arena serve", flag.ContinueOnError)
226		args.SetOutput(os.Stdout)
227		host := args.String("host", "127.0.0.1", "address to bind")
228		port := args.Int("port", 8080, "port to bind; 0 selects an available port")
229		data := args.String("data-dir", "data", "directory for local records")
230		if err := args.Parse(os.Args[2:]); errors.Is(err, flag.ErrHelp) {
231			return nil
232		} else if err != nil {
233			return err
234		}
235		if args.NArg() != 0 {
236			return errors.New("unexpected positional argument")
237		}
238		if *port < 0 || *port > 65535 {
239			return errors.New("port must be between 0 and 65535")
240		}
241		if err := os.MkdirAll(*data, 0700); err != nil {
242			return err
243		}
244		dataFile := filepath.Join(*data, "rooms.json")
245		store := newRoomStore(dataFile)
246	
247		// 首次启动时初始化空数组；已存在则原样保留。
248		file, err := os.OpenFile(dataFile, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
249		if err == nil {
250			_, writeErr := file.WriteString("[]\n")
251			closeErr := file.Close()
252			if writeErr != nil {
253				return writeErr
254			}
255			if closeErr != nil {
256				return closeErr
257			}
258		} else if !errors.Is(err, os.ErrExist) {
259			return err
260		}
261	
262		mux := http.NewServeMux()
263		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
264			if r.URL.Path != "/" {
265				respond(w, http.StatusNotFound, map[string]string{"error": "not found"})
266				return
267			}
268			if r.Method != http.MethodGet {
269				methodNotAllowed(w, "GET")
270				return
271			}
272			w.Header().Set("Content-Type", "text/html; charset=utf-8")
273			_, _ = w.Write(indexPage)
274		})
275		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
276			if r.Method != http.MethodGet {
277				methodNotAllowed(w, "GET")
278				return
279			}
280			respond(w, http.StatusOK, map[string]string{"status": "ok", "product": product})
281		})
282		mux.HandleFunc("/api/rooms", func(w http.ResponseWriter, r *http.Request) {
283			switch r.Method {
284			case http.MethodGet:
285				store.mu.Lock()
286				records, _, err := store.load()
287				store.mu.Unlock()
288				if err != nil {
289					respond(w, http.StatusInternalServerError, map[string]string{"error": "无法读取房间数据：" + err.Error()})
290					return
291				}
292				respond(w, http.StatusOK, map[string]any{resourceName: records})
293			case http.MethodPost:
294				handleCreateRoom(w, r, store)
295			default:
296				methodNotAllowed(w, "GET, POST")
297			}
298		})
299	
300		server := &http.Server{
301			Handler:           mux,
302			ReadHeaderTimeout: 5 * time.Second,
303		}
304		listener, err := net.Listen("tcp", net.JoinHostPort(*host, fmt.Sprint(*port)))
305		if err != nil {
306			return err
307		}
308		fmt.Printf("%s listening on http://%s\n", product, listener.Addr().String())
309		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
310		defer stop()
311		failures := make(chan error, 1)
312		go func() { failures <- server.Serve(listener) }()
313		select {
314		case err := <-failures:
315			if !errors.Is(err, http.ErrServerClosed) {
316				return err
317			}
318		case <-ctx.Done():
319			shutdown, cancel := context.WithTimeout(context.Background(), 3*time.Second)
320			defer cancel()
321			if err := server.Shutdown(shutdown); err != nil {
322				return err
323			}
324		}
325		return nil
326	}
327	
328	func handleCreateRoom(w http.ResponseWriter, r *http.Request, store *roomStore) {
329		// 限制请求体大小，避免异常大载荷。
330		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 1<<20))
331		if err != nil {
332			respond(w, http.StatusBadRequest, map[string]string{"error": "读取请求体失败：" + err.Error()})
333			return
334		}
335	
336		cfg, ok := parseRoomFields(w, body)
337		if !ok {
338			return
339		}
340	
341		newRoom, status, err := store.create(cfg)
342		if err != nil {
343			respond(w, status, map[string]string{"error": err.Error()})
344			return
345		}
346		respond(w, http.StatusCreated, newRoom)
347	}
348	
349	func parseRoomFields(w http.ResponseWriter, body []byte) (roomConfig, bool) {
350		var fields map[string]json.RawMessage
351		if err := json.Unmarshal(body, &fields); err != nil || fields == nil {
352			respond(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是单个 JSON 对象"})
353			return roomConfig{}, false
354		}
355	
356		var cfg roomConfig
357		missing := func(key string) (roomConfig, bool) {
358			respond(w, http.StatusBadRequest, map[string]string{"error": "缺少必填字段：" + key})
359			return roomConfig{}, false
360		}
361	
362		rawName, ok := fields["name"]
363		if !ok {
364			return missing("name")
365		}
366		if err := json.Unmarshal(rawName, &cfg.Name); err != nil {
367			respond(w, http.StatusBadRequest, map[string]string{"error": "name 必须是字符串"})
368			return roomConfig{}, false
369		}
370	
371		rawGame, ok := fields["game"]
372		if !ok {
373			return missing("game")
374		}
375		if err := json.Unmarshal(rawGame, &cfg.Game); err != nil {
376			respond(w, http.StatusBadRequest, map[string]string{"error": "game 必须是字符串"})
377			return roomConfig{}, false
378		}
379	
380		rawCapacity, ok := fields["capacity"]
381		if !ok {
382			return missing("capacity")
383		}
384		capacity, err := parseStrictInt(rawCapacity)
385		if err != nil {
386			respond(w, http.StatusBadRequest, map[string]string{"error": "capacity 必须是整数：" + err.Error()})
387			return roomConfig{}, false
388		}
389		cfg.Capacity = capacity
390	
391		rawTurn, ok := fields["turnSeconds"]
392		if !ok {
393			return missing("turnSeconds")
394		}
395		turn, err := parseStrictInt(rawTurn)
396		if err != nil {
397			respond(w, http.StatusBadRequest, map[string]string{"error": "turnSeconds 必须是整数：" + err.Error()})
398			return roomConfig{}, false
399		}
400		cfg.TurnSeconds = turn
401	
402		return cfg, true
403	}
404	
405	// parseStrictInt 只接受单个 JSON 整数（拒绝小数、科学计数法、字符串、布尔、null、对象、数组及尾随内容）。
406	func parseStrictInt(raw json.RawMessage) (int, error) {
407		dec := json.NewDecoder(strings.NewReader(string(raw)))
408		dec.UseNumber()
409		var v any
410		if err := dec.Decode(&v); err != nil {
411			return 0, errors.New("值不是数字")
412		}
413		var extra any
414		if err := dec.Decode(&extra); err != io.EOF {
415			return 0, errors.New("包含多余内容")
416		}
417		// 带引号的字符串会解成 Go string 而非 json.Number，断言失败即可拒绝。
418		n, ok := v.(json.Number)
419		if !ok {
420			return 0, errors.New("值不是数字")
421		}
422		i, err := n.Int64()
423		if err != nil {
424			return 0, errors.New("不是整数（不接受小数）")
425		}
426		return int(i), nil
427	}
428	
429	func printHelp() {
430		fmt.Println("ScoreArena - 桌面规则游戏与赛事管理")
431		fmt.Println("Usage: go run . serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]")
432		fmt.Println("       go run . --help")
433		fmt.Println("Defaults: --host 127.0.0.1 --port 8080 --data-dir data")
434	}
435	
436	func main() {
437		if err := run(); err != nil {
438			fmt.Fprintln(os.Stderr, err)
439			os.Exit(1)
440		}
441	}
