331			t.Fatalf("状态码 = %d，期望 500，响应: %v", status, body)
332		}
333		errMsg, _ := body["error"].(string)
334		if !strings.Contains(errMsg, "失败") || !strings.Contains(errMsg, "数据") {
335			t.Fatalf("error 应明确说明保存失败，实际: %q", errMsg)
336		}
337		if _, ok := body["id"]; ok {
338			t.Fatalf("保存失败不应返回成功房间，实际: %v", body)
339		}
340	
341		// 原数据完整可读：数量、内容和附带字段与创建前一致。
342		assertRoomsUnchanged(t, baseURL, dataDir, seed)
343	}
344	
345	// 名称首尾空白采用 Unicode 空白范围：U+0085、U+00A0 等应去掉，
346	// U+FEFF 不属于该范围，应保留并计入长度；内部空白原样保留。
347	func TestCreateRoomTrimsUnicodeWhitespaceButKeepsFEFF(t *testing.T) {
348		dataDir := t.TempDir()
349		seedRooms(t, dataDir, seedRecord1, seedRecord2)
350		baseURL := startServer(t, dataDir)
351	
352		rawName := "\u0085\u00a0\ufeff深夜\ufeff 对局\ufeff \u00a0\u0085"
353		wantName := "\ufeff深夜\ufeff 对局\ufeff"
354		body, _ := json.Marshal(map[string]any{"name": rawName, "game": "ludo", "capacity": 3, "turnSeconds": 60})
355		status, created := postRoom(t, baseURL, string(body))
356		if status != http.StatusCreated {
357			t.Fatalf("创建状态码 = %d，期望 201，响应: %v", status, created)
358		}
359		if got := created["name"]; got != wantName {
360			t.Fatalf("名称 = %q，期望 %q（U+0085/U+00A0 去掉，U+FEFF 保留，内部空格不动）", got, wantName)
361		}
362	
363		// 仅由 U+FEFF 组成的名称长度为 1 个码点，是合法名称。
364		body, _ = json.Marshal(map[string]any{"name": "\ufeff", "game": "gomoku", "capacity": 2, "turnSeconds": 0})
365		status, created = postRoom(t, baseURL, string(body))
366		if status != http.StatusCreated {
367			t.Fatalf("U+FEFF 名称创建状态码 = %d，期望 201，响应: %v", status, created)
368		}
369		if got := created["name"]; got != "\ufeff" {
370			t.Fatalf("名称 = %q，期望 %q（U+FEFF 保留并计入长度）", got, "\ufeff")
371		}
372	}
373	
374	// 名称长度按 Unicode 码点计：恰好 40 个码点（含补充平面表情）可以创建，
375	// 41 个码点必须拒绝，且不产生新房间、不改变已有数据。
376	func TestCreateRoomNameLengthBoundary(t *testing.T) {
377		dataDir := t.TempDir()
378		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
379		baseURL := startServer(t, dataDir)
380	
381		name40 := strings.Repeat("棋", 39) + "😀"
382		body, _ := json.Marshal(map[string]any{"name": name40, "game": "gomoku", "capacity": 2, "turnSeconds": 0})
383		status, created := postRoom(t, baseURL, string(body))
384		if status != http.StatusCreated {
385			t.Fatalf("40 码点名称创建状态码 = %d，期望 201，响应: %v", status, created)
386		}
387		if got := created["name"]; got != name40 {
388			t.Fatalf("保存的名称 = %q，期望 %q", got, name40)
389		}
390	
391		name41 := strings.Repeat("棋", 40) + "😀"
392		body, _ = json.Marshal(map[string]any{"name": name41, "game": "gomoku", "capacity": 2, "turnSeconds": 0})
393		status, rejected := postRoom(t, baseURL, string(body))
394		if status != http.StatusBadRequest {
395			t.Fatalf("41 码点名称状态码 = %d，期望 400，响应: %v", status, rejected)
396		}
397		errMsg, _ := rejected["error"].(string)
398		if !strings.Contains(errMsg, "40") {
399			t.Fatalf("error 应说明超过 40 个字符，实际: %q", errMsg)
400		}
401		if _, ok := rejected["id"]; ok {
402			t.Fatalf("被拒绝的请求不应返回房间编号，实际: %v", rejected)
403		}
404	
405		// 只有 40 码点那一条被追加，拒绝的请求不产生记录，种子记录保持不变。
406		_, rooms := getRooms(t, baseURL)
407		if len(rooms) != 3 {
408			t.Fatalf("房间数量 = %d，期望 3（种子 2 条 + 40 码点 1 条）", len(rooms))
409		}
410		if want := decodeRecords(t, seed); !reflect.DeepEqual(rooms[:2], want) {
411			t.Fatalf("种子记录被改动：\n得到: %v\n期望: %v", rooms[:2], want)
412		}
413	}
414	
415	// seedRaw 以原始字节写入 rooms.json，用于构造损坏或形态异常的历史数据。
416	func seedRaw(t *testing.T, dataDir string, content string) []byte {
417		t.Helper()
418		raw := []byte(content)
419		if err := os.WriteFile(filepath.Join(dataDir, "rooms.json"), raw, 0o644); err != nil {
420			t.Fatalf("写入种子数据失败: %v", err)
421		}
422		return raw
423	}
424	
425	// getRoomsResponse 查询房间列表，返回状态码与解码后的响应体（成功或失败均可）。
426	func getRoomsResponse(t *testing.T, baseURL string) (int, map[string]any) {
427		t.Helper()
428		resp, err := httpClient.Get(baseURL + "/api/rooms")
429		if err != nil {
430			t.Fatalf("GET /api/rooms 失败: %v", err)
431		}
432		defer resp.Body.Close()
433		payload, err := io.ReadAll(resp.Body)
434		if err != nil {
435			t.Fatalf("读取响应失败: %v", err)
436		}
437		var decoded map[string]any
438		if err := json.Unmarshal(payload, &decoded); err != nil {
439			t.Fatalf("响应不是合法 JSON: %v（内容: %s）", err, payload)
440		}
441		return resp.StatusCode, decoded
442	}
443	
444	// assertCreateFailsOnUnreadableData 在历史数据读不出来的前提下提交一份完全合法的房间配置，
445	// 断言：创建返回 500 且 error 指向房间数据的读取/解析问题（而非用户输入），
446	// 不返回新房间编号或成功房间对象；查询同一份数据同样返回 500 而不是空列表；
447	// 磁盘上的原始数据逐字节保持不变（不清空、不改写、不追加、不修复）。
448	func assertCreateFailsOnUnreadableData(t *testing.T, baseURL, dataDir string, seed []byte) {
449		t.Helper()
450	
451		status, body := postRoom(t, baseURL, `{"name":"读取保护验证房","game":"gomoku","capacity":2,"turnSeconds":30}`)
452		if status != http.StatusInternalServerError {
453			t.Fatalf("创建状态码 = %d，期望 500，响应: %v", status, body)
454		}
455		errMsg, _ := body["error"].(string)
456		if errMsg == "" {
457			t.Fatalf("读取失败时响应应包含非空 error，实际: %v", body)
458		}
459		if !strings.Contains(errMsg, "房间数据") {
460			t.Fatalf("error 应说明问题出在房间数据的读取或解析，实际: %q", errMsg)
461		}
462		if strings.Contains(errMsg, "缺少必填字段") || strings.Contains(errMsg, "不能为空") {
463			t.Fatalf("error 不应把读取失败归为用户漏填字段或配置不合法，实际: %q", errMsg)
464		}
465		if _, ok := body["id"]; ok {
466			t.Fatalf("读取失败不应返回新房间编号，实际: %v", body)
467		}
468		if _, ok := body["rooms"]; ok {
469			t.Fatalf("读取失败不应返回成功的房间对象或列表，实际: %v", body)
470		}
471	
472		// 查询同一份数据也应明确报 500，不能以成功的空列表掩盖问题。
473		getStatus, getBody := getRoomsResponse(t, baseURL)
474		if getStatus != http.StatusInternalServerError {
475			t.Fatalf("GET /api/rooms 状态码 = %d，期望 500，响应: %v", getStatus, getBody)
476		}
477		getErr, _ := getBody["error"].(string)
478		if !strings.Contains(getErr, "房间数据") {
479			t.Fatalf("GET 的 error 应说明房间数据读取失败，实际: %q", getErr)
480		}
481		if _, ok := getBody["rooms"]; ok {
482			t.Fatalf("读取失败不应返回房间列表，实际: %v", getBody)
483		}
484	
485		// 原数据逐字节保持不变：内容、顺序、附带字段不动，也没有本次提交的新记录。
486		if got := readDataFile(t, dataDir); !bytes.Equal(got, seed) {
487			t.Fatalf("数据文件被改动：\n得到: %s\n期望: %s", got, seed)
488		}
489	}
490	
491	// 已有数据被截断、缺少结束符而无法解析时，即使前半段仍能辨认出已有房间，
492	// 合法创建也必须返回 500，不能丢弃可解析部分后继续追加，原数据保持不变。
493	func TestCreateRoomFailsWhenDataTruncated(t *testing.T) {
494		dataDir := t.TempDir()
495		// 前半段是两条完整可辨的房间记录，但整体缺少收尾，无法作为数组解析。
496		seed := seedRaw(t, dataDir, "[\n"+seedRecord1+",\n"+seedRecord2+",\n{\"id\":\"seed-ga")
497		baseURL := startServer(t, dataDir)
498	
499		assertCreateFailsOnUnreadableData(t, baseURL, dataDir, seed)
500	}
501	
502	// 已有内容是完整 JSON 却是一个对象而不是房间数组时，
503	// 合法创建必须返回 500，不能当成没有房间后用新记录覆盖。
504	func TestCreateRoomFailsWhenDataIsObjectNotArray(t *testing.T) {
505		dataDir := t.TempDir()
506		seed := seedRaw(t, dataDir, "{\n  \"rooms\": [\n"+seedRecord1+"\n  ]\n}\n")
507		baseURL := startServer(t, dataDir)
508	
509		assertCreateFailsOnUnreadableData(t, baseURL, dataDir, seed)
510	}
511	
512	// 已有内容是带正常 JSON 空白的空数组时，属于合法空列表：
513	// 创建应照常返回 201，查询能得到与创建响应一致的那一个新房间。
514	func TestCreateRoomOnEmptyArrayWithWhitespace(t *testing.T) {
515		dataDir := t.TempDir()
516		seedRaw(t, dataDir, "  [\n]\n")
517		baseURL := startServer(t, dataDir)
518	
519		status, created := postRoom(t, baseURL, `{"name":"空白环绕的空列表","game":"ludo","capacity":3,"turnSeconds":60}`)
520		if status != http.StatusCreated {
521			t.Fatalf("创建状态码 = %d，期望 201，响应: %v", status, created)
522		}
523		if id, _ := created["id"].(string); id == "" {
524			t.Fatal("新房间编号为空")
525		}
526	
527		listStatus, rooms := getRooms(t, baseURL)
528		if listStatus != http.StatusOK {
529			t.Fatalf("GET /api/rooms 状态码 = %d，期望 200", listStatus)
530		}
531		if len(rooms) != 1 {
532			t.Fatalf("房间数量 = %d，期望 1", len(rooms))
533		}
534		if !reflect.DeepEqual(rooms[0], created) {
535			t.Fatalf("列表中的记录与创建响应不一致：\n列表: %v\n响应: %v", rooms[0], created)
536		}
537	}
538	
539	// 已有数据只有空白、没有数组内容时，不能套用首次使用的空列表行为，
540	// 应按解析失败处理：创建返回 500，原数据保持不变。
541	func TestCreateRoomFailsWhenDataOnlyWhitespace(t *testing.T) {
542		dataDir := t.TempDir()
543		seed := seedRaw(t, dataDir, "  \n\t \n")
544		baseURL := startServer(t, dataDir)
545	
546		assertCreateFailsOnUnreadableData(t, baseURL, dataDir, seed)
547	}
548	
549	// 只含会被去掉的首尾空白（含 U+0085、U+00A0）的名称视为空，
550	// 返回 400 并说明名称不能为空，不返回新房间编号，已有数据保持不变。
551	func TestCreateRoomRejectedWhenNameOnlyWhitespace(t *testing.T) {
552		dataDir := t.TempDir()
553		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
554		baseURL := startServer(t, dataDir)
555	
556		body, _ := json.Marshal(map[string]any{"name": "  \u00a0 \u0085  ", "game": "gomoku", "capacity": 2, "turnSeconds": 0})
557		status, rejected := postRoom(t, baseURL, string(body))
558		if status != http.StatusBadRequest {
559			t.Fatalf("状态码 = %d，期望 400，响应: %v", status, rejected)
560		}
561		errMsg, _ := rejected["error"].(string)
562		if !strings.Contains(errMsg, "不能为空") {
563			t.Fatalf("error 应说明名称不能为空，实际: %q", errMsg)
564		}
565		if _, ok := rejected["id"]; ok {
566			t.Fatalf("被拒绝的请求不应返回房间编号，实际: %v", rejected)
567		}
568	
569		assertRoomsUnchanged(t, baseURL, dataDir, seed)
570	}
